node -e '
const fs=require("fs");
const regions=["north","south","east","west"];
const inspector={north:{count:10,units:90,weighted:167},south:{count:10,units:94,weighted:171},east:{count:10,units:98,weighted:209},west:{count:10,units:85,weighted:145}};
const out={};
for(const r of regions){
  const raw=fs.readFileSync(r+".json","utf8");
  const data=JSON.parse(raw);
  if(!Array.isArray(data)) throw new Error(r+" not array");
  const ids=data.map(x=>x.id);
  const count=data.length;
  const units=data.reduce((a,x)=>a+x.units,0);
  const weighted=data.reduce((a,x)=>a+x.units*x.weight,0);
  const okFields=data.every(x=>Number.isInteger(x.id)&&Number.isInteger(x.units)&&Number.isInteger(x.weight)&&Object.keys(x).length===3);
  const uniqueIds=new Set(ids).size===ids.length;
  const contiguous=ids.every((v,i)=>v===i+1);
  out[r]={count,units,weighted};
  console.log(r,JSON.stringify({count,units,weighted}),"records="+count,"uniqueIds="+uniqueIds,"ids1..n="+contiguous,"fieldsOK="+okFields,"bytes="+raw.length);
  console.log("  recompute vs inspector:",JSON.stringify(out[r])===JSON.stringify(inspector[r])?"MATCH":"MISMATCH");
}
const grand_units=regions.reduce((a,r)=>a+out[r].units,0);
const grand_weighted=regions.reduce((a,r)=>a+out[r].weighted,0);
const answer={regions:out,grand_units,grand_weighted};
fs.writeFileSync("answer.json",JSON.stringify(answer,null,2)+"\n");
console.log("grand_units",grand_units,"grand_weighted",grand_weighted);
'

